//! Byte-for-byte parity with the Python `protocol.py` (fixtures generated by
//! `scripts/app/gen_edopro_fixtures.py`).

use decklight_edopro::protocol::*;
use serde_json::Value;

fn fixtures() -> Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/protocol.json");
    serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap()
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn info(v: &Value) -> HostInfo {
    let n = |k: &str| v[k].as_u64().unwrap() as u32;
    let u8v = |k: &str| v[k].as_u64().unwrap() as u8;
    let u16v = |k: &str| v[k].as_u64().unwrap() as u16;
    let i32v = |k: &str| v[k].as_i64().unwrap() as i32;
    HostInfo {
        lflist: n("lflist"),
        rule: u8v("rule"),
        mode: u8v("mode"),
        duel_rule: u8v("duel_rule"),
        no_check_deck_content: u8v("no_check_deck_content"),
        no_shuffle_deck: u8v("no_shuffle_deck"),
        start_lp: n("start_lp"),
        start_hand: u8v("start_hand"),
        draw_count: u8v("draw_count"),
        time_limit: u16v("time_limit"),
        duel_flag_high: n("duel_flag_high"),
        handshake: n("handshake"),
        version: v["version"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as u8).collect::<Vec<_>>().try_into().unwrap(),
        team1: i32v("team1"),
        team2: i32v("team2"),
        best_of: i32v("best_of"),
        duel_flag_low: n("duel_flag_low"),
        forbiddentypes: n("forbiddentypes"),
        extra_rules: u16v("extra_rules"),
        main_min: u16v("main_min"),
        main_max: u16v("main_max"),
        extra_min: u16v("extra_min"),
        extra_max: u16v("extra_max"),
        side_min: u16v("side_min"),
        side_max: u16v("side_max"),
    }
}

#[test]
fn hostinfo() {
    for case in fixtures()["hostinfo"].as_array().unwrap() {
        let want = hex(case["hex"].as_str().unwrap());
        let h = info(&case["fields"]);
        assert_eq!(h.pack(), want);
        assert_eq!(HostInfo::unpack(&want).unwrap(), h);
    }
}

#[test]
fn join_game() {
    for case in fixtures()["join_game"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        let version = a[0].as_u64().unwrap() as u16;
        let gameid = a[1].as_u64().unwrap() as u32;
        let v2: [u8; 4] =
            a[2].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as u8).collect::<Vec<_>>().try_into().unwrap();
        let pw = a[3].as_str().unwrap();
        let want = hex(case["hex"].as_str().unwrap());
        assert_eq!(pack_join_game(version, gameid, v2, pw), want);
        assert_eq!(unpack_join_game(&want).unwrap(), (version, gameid, v2));
    }
}

#[test]
fn create_game() {
    let f = fixtures();
    for case in f["create_game"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        let idx = a[0].as_u64().unwrap() as usize;
        let h = info(&f["hostinfo"][idx]["fields"]);
        let want = hex(case["hex"].as_str().unwrap());
        assert_eq!(pack_create_game(&h, a[1].as_str().unwrap(), a[2].as_str().unwrap(), a[3].as_str().unwrap()), want);
        assert_eq!(want.len(), 348);
    }
}

#[test]
fn player_enter_and_info() {
    for case in fixtures()["hs_player_enter"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        let (name, pos) = (a[0].as_str().unwrap(), a[1].as_u64().unwrap() as u8);
        let want = hex(case["hex"].as_str().unwrap());
        assert_eq!(pack_hs_player_enter(name, pos), want);
        assert_eq!(parse_hs_player_enter(&want).unwrap(), (name.to_string(), pos));
        assert_eq!(want.len(), 42);
    }
    for case in fixtures()["player_info"].as_array().unwrap() {
        let name = case["args"][0].as_str().unwrap();
        assert_eq!(pack_player_info(name), hex(case["hex"].as_str().unwrap()));
    }
}

#[test]
fn update_deck() {
    for case in fixtures()["update_deck"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        let list = |i: usize| a[i].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as u32).collect::<Vec<_>>();
        let (main, extra, side) = (list(0), list(1), list(2));
        let want = hex(case["hex"].as_str().unwrap());
        assert_eq!(pack_update_deck(&main, &extra, &side), want);
        let (me, s) = parse_update_deck(&want).unwrap();
        assert_eq!(me, [main.clone(), extra.clone()].concat());
        assert_eq!(s, side);
    }
}

#[test]
fn small_packets() {
    let f = fixtures();
    for case in f["hand_choice"].as_array().unwrap() {
        let n = case["args"][0].as_u64().unwrap() as u8;
        assert_eq!(pack_hand_choice(n).unwrap(), hex(case["hex"].as_str().unwrap()));
    }
    for case in f["tp_choice"].as_array().unwrap() {
        let b = case["args"][0].as_bool().unwrap();
        assert_eq!(pack_tp_choice(b), hex(case["hex"].as_str().unwrap()));
    }
    for case in f["hand_result"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        assert_eq!(pack_hand_result(a[0].as_u64().unwrap() as u8, a[1].as_u64().unwrap() as u8), hex(case["hex"].as_str().unwrap()));
    }
    for case in f["join_error"].as_array().unwrap() {
        let code = case["args"][0].as_u64().unwrap() as u32;
        assert_eq!(pack_join_error(code), hex(case["hex"].as_str().unwrap()));
    }
    for case in f["deck_error"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        let v: Vec<u32> = a.iter().map(|x| x.as_u64().unwrap() as u32).collect();
        assert_eq!(pack_deck_error(v[0], v[1], v[2], v[3], v[4]), hex(case["hex"].as_str().unwrap()));
    }
    for case in f["start"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        let v: Vec<u32> = a.iter().map(|x| x.as_u64().unwrap() as u32).collect();
        assert_eq!(build_start(v[0], v[1], v[2], v[3], v[4], v[5] as u8), hex(case["hex"].as_str().unwrap()));
    }
    for case in f["frame"].as_array().unwrap() {
        let a = case["args"].as_array().unwrap();
        assert_eq!(pack_frame(a[0].as_u64().unwrap() as u8, &hex(a[1].as_str().unwrap())), hex(case["hex"].as_str().unwrap()));
    }
}

#[test]
fn error_messages() {
    for case in fixtures()["error_msg"].as_array().unwrap() {
        let raw = hex(case["hex"].as_str().unwrap());
        assert_eq!(parse_error_msg(&raw), case["text"].as_str().unwrap());
    }
}

#[test]
fn parsers() {
    let f = fixtures();
    for case in f["parse_type_change"].as_array().unwrap() {
        let w = case["want"].as_array().unwrap();
        assert_eq!(
            parse_type_change(&hex(case["hex"].as_str().unwrap())).unwrap(),
            (w[0].as_u64().unwrap() as u8, w[1].as_bool().unwrap())
        );
    }
    for case in f["parse_hs_player_change"].as_array().unwrap() {
        let w = case["want"].as_array().unwrap();
        assert_eq!(
            parse_hs_player_change(&hex(case["hex"].as_str().unwrap())).unwrap(),
            (w[0].as_u64().unwrap() as u8, w[1].as_str().unwrap().to_string())
        );
    }
    for case in f["parse_time_limit"].as_array().unwrap() {
        let w = case["want"].as_array().unwrap();
        assert_eq!(
            parse_time_limit(&hex(case["hex"].as_str().unwrap())).unwrap(),
            (w[0].as_u64().unwrap() as u8, w[1].as_u64().unwrap() as u16)
        );
    }
    for case in f["parse_hand_result"].as_array().unwrap() {
        let w = case["want"].as_array().unwrap();
        assert_eq!(
            parse_hand_result(&hex(case["hex"].as_str().unwrap())).unwrap(),
            (w[0].as_u64().unwrap() as u8, w[1].as_u64().unwrap() as u8)
        );
    }
    for case in f["parse_tp_result"].as_array().unwrap() {
        assert_eq!(parse_tp_result(&hex(case["hex"].as_str().unwrap())).unwrap(), case["want"].as_bool().unwrap());
    }
    for case in f["parse_create_game"].as_array().unwrap() {
        let frame = hex(case["hex"].as_str().unwrap());
        assert_eq!(parse_create_game(&frame[3..]).unwrap(), case["want"].as_u64().unwrap() as u32);
    }
}
